1	import {createChatOrchestrator} from './chatOrchestrator.js';
2	import type {MessageChunk, UsageMetadata} from '../types/ai.js';
3	import type {ChatSession} from '../types/session.js';
4	import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
5	import {ToolRegistry} from './tools/registry.js';
6	import {scriptedProvider} from './scriptedProviderTestSupport.js';
7	
8	const SENT_AT = '2026-01-01T00:00:00.000Z';
9	const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});
10	const toolCall: MessageChunk = {type: 'tool_use', toolCall: {id: 'call-1', name: 'lookup', input: {q: 'x'}}};
11	const toolStop = (usage?: UsageMetadata): MessageChunk => ({type: 'stop', stopReason: 'tool_use', usage});
12	const doneStop = (usage?: UsageMetadata): MessageChunk => ({type: 'stop', stopReason: 'end_turn', usage});
13	
14	function createSession(): ChatSession {
15	  return {
16	    sessionId: 's1',
17	    userId: 'u1',
18	    entries: [{role: 'user', content: 'ask', timestamp: SENT_AT}],
19	  };
20	}
21	
22	function lookupTool(): ToolRegistry {
23	  const registry = new ToolRegistry();
24	  registry.register({name: 'lookup', description: 'looks things up', inputSchema: {type: 'object'}}, async () => ({
25	    result: 'found it',
26	  }));
27	  return registry;
28	}
29	
30	describe('afterModelResponse usage aggregation acceptance', () => {
31	  it('reports the usage from every provider call across two tool rounds', async () => {
32	    const seen: UsageMetadata[] = [];
33	    const provider = scriptedProvider([
34	      [toolCall, toolStop({inputTokens: 10, outputTokens: 2, totalTokens: 12})],
35	      [toolCall, toolStop({inputTokens: 20, outputTokens: 4, totalTokens: 24})],
36	      [{type: 'text', text: 'done'}, doneStop({inputTokens: 30, outputTokens: 6, totalTokens: 36})],
37	    ]);
38	    const orchestrator = createChatOrchestrator(provider, promptBuilder, lookupTool(), {
39	      hooks: {
40	        afterModelResponse: async (_session, _text, usage) => {
41	          seen.push(usage as UsageMetadata);
42	        },
43	      },
44	    });
45	
46	    await orchestrator.processMessage(createSession());
47	
48	    expect(seen).toEqual([{inputTokens: 60, outputTokens: 12, totalTokens: 72}]);
49	  });
